<div class="page-section page-section-0" id="pageSection-0">
            <section data-uuid="1905f1ad-7705-4abc-a5a0-af0e84617a81" data-location-lat="" data-location-lng=""  class="section padd-top-md padd-bottom-md marg-top-md marg-bottom-md" ><header class="section-header-wrapper grid-container grid-default container-min"><div class="section-header text-center"><div class="section-titles flex-container flex-dir-column align-middle align-center text-center"><div class="section-texts has-pretitle has-title"><span class="section-pretitle block-span">Révéler</span><h2 class="section-title">les richesses du littoral</h2></div></div></div></header><article class="section-layout-wrapper grid-container grid-default"><div class="grid_1col_tpl_01 grid-x align-middle grid-padding-x grid-padding-y"><div class="cell xmedium-down-order-9"><div class="woody-component woody-component-focus tpl_121 no-sessions" data-equalizer="data-equalizer"><div class="woody-mobile-swiper swiper swiper-container " ><div class="grid-x grid-padding-x grid-padding-y  " data-equalizer="data-equalizer" role="list"><div class="cell swRespS " role="listitem"><div class="card splitCard media-right tpl_03 isRel  entree-de-rubrique ratio_2_1" data-postid="1809"  data-card-display-options="&#x7B;&quot;display_elements&quot;&#x3A;&#x5B;&quot;description&quot;&#x5D;,&quot;display_button&quot;&#x3A;false&#x7D;"><a class="card-link" href="/explorez/le-littoral-et-les-lacs/profiter-du-littoral" target="_self"><div class="grid-x  flex-dir-row-reverse"><div class="cell large-8">@endverbatim<x-media.figure
